import { existsSync, writeFileSync } from "node:fs";

// Runs once: the marker file stops it from resetting a later user choice.
export function migrateBackgroundSend(settings: Settings, markerPath: string) {
  if (existsSync(markerPath)) return settings;
  writeFileSync(markerPath, "done");
  return { ...settings, "thread.sendToBackground": "mod+enter" };
}

