const POLL_MS = 120_000;

export function startPrWatcher(prs: PullRequestStore, github: GitHub) {
  const timers = new Map<string, NodeJS.Timeout>();
  const poll = async (url: string) => {
    const state = await github.readPullRequest(url);
    if (state.changed) prs.wake(url, state);
  };
  return {
    watch(url: string) {
      timers.set(url, setInterval(() => void poll(url), POLL_MS));
    },
    stop(url: string) {
      clearInterval(timers.get(url));
      timers.delete(url);
    },
  };
}

import { Semaphore } from "./semaphore";

export function startPrWatcher(prs: PullRequestStore, github: GitHub, settings: Settings) {
  const timers = new Map<string, NodeJS.Timeout>();
  const lock = new Semaphore(1);
  const poll = async (url: string) => {
    try {
      const state = await github.readPullRequest(url);
      if (state.closed) return stop(url);
      if (state.changed) await lock.run(() => prs.wake(url, state));
    } catch (error) {
      log.warn(`PR watch failed for ${url}`, error);
      backoff(url);
    }
  };
  const stop = (url: string) => lock.run(() => {
    clearInterval(timers.get(url));
    timers.delete(url);
  });
  return {
    watch(url: string) {
      timers.set(url, setInterval(() => void poll(url), settings.prPollMs));
    },
    stop,
  };
}

test('unwatch stops polling', async () => {
  const watcher = startPrWatcher(store, github, settings);
  watcher.watch(url);
  await watcher.stop(url);
  expect(github.readPullRequest).not.toHaveBeenCalled();
});

